def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main():
    print("Business OS v13 - Blueprint Compatibility Repair")
    print(f"Repository: {ROOT}\n")
    if ROOT.name != "Business-OS":
        raise SystemExit("ABORT: installer must run from the Business-OS repository scripts folder.")
    print("Verifying exact post-Creative-Director source...")
    for rel, expected in EXPECTED.items():
        path = ROOT / rel
        if not path.exists():
            raise SystemExit(f"ABORT: missing required file: {rel}")
        actual = sha(path)
        if actual != expected:
            raise SystemExit(f"ABORT: {rel} changed since inspection. Expected {expected}, got {actual}. Nothing was modified.")
        print(f"  OK {rel}")

    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    backup = ROOT / ".v13_backups" / f"compatibility-{stamp}"
    for rel in EXPECTED:
        src = ROOT / rel
        dst = backup / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dst)
    print(f"\nBackup created: {backup}")

    for rel, content in FILES.items():
        path = ROOT / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8", newline="\n")

    print("\nPASS: strict v1 read-compatibility adapter installed")
    print("PASS: stored legacy blueprint JSON remains immutable")
    print("PASS: new concepts remain strict native schema v2")
    print("PASS: malformed legacy blueprints still fail closed")
    print("PASS: compatibility regression test installed")
    print("\nNext verification commands:")
    print("  python -m compileall app.py services scripts")
    print("  python scripts/test_v12_schema.py")
    print("  python scripts/test_v12_renderer.py")
    print("  python scripts/test_v13_foundation.py")
    print("  python scripts/test_v13_creative_director.py")
    print("  python scripts/test_v13_compatibility.py")
    print("  git diff --check")
    print("  git status --short")
    print("\nDo not commit/tag yet. Re-open the existing prospect concept history after verification.")

if __name__ == "__main__":
    main()
